	/** Returns, given a field and a table, the maximum value of the field in the table. */
	synchronized static public int getMaxValue(String pField, String pTable)
			throws EntityNotFoundException, ConnectionException, SQLException {

		int value = 0;
		Connection connect = null;
		try {
			/** If the field and the table were not provided, we return an error code */
			if (pField.equals(""))
				throw new EntityNotFoundException();
			if (pTable.equals(""))
				throw new EntityNotFoundException();

			/** We prepare the SQL string to retrieve the requested information */
			String tSql = "SELECT max(" + pField + ") as new_field FROM "
					+ pTable;

			// We obtain a connection to the database
			connect = DBConnection.getConnection();
			if (connect == null)
				throw new ConnectionException();

			// We send the query to the database
			ResultSet tRs = Utility.queryOperation(connect, tSql);

			if (tRs.next())
				value = tRs.getInt("new_field");
			else
				throw new EntityNotFoundException();

			return value;
		} finally {
			DBConnection.releaseConnection(connect);
		}
	}

	/** Converts a date into a string formatted for the database. */
	static public String date2SQLString(java.util.Date pDate, boolean pHour) {

		TimeZone tz = TimeZone.getDefault();
		Calendar calendar = Calendar.getInstance(tz);
		calendar.setTime(pDate);


		int year = calendar.get(Calendar.YEAR);
		int month = calendar.get(Calendar.MONTH) + 1;
		int day = calendar.get(Calendar.DATE);

		String result = year + "-" + month + "-" + day ;

		int hour = calendar.get(Calendar.HOUR_OF_DAY);
		int min = calendar.get(Calendar.MINUTE);
		int sec = calendar.get(Calendar.SECOND);

		if (pHour){
			result = result + " " + hour + ":" + min + ":" + sec; 
		}


		return result;
	}

